import React, { useState } from 'react';
import './Booking.css'; // استيراد ملف CSS الخارجي

export default function RestaurantBooking() {
  const [formData, setFormData] = useState({
    location: '',
    cuisine: '',
    date: '',
    time: '',
    partySize: ''
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      await new Promise(resolve => setTimeout(resolve, 1500));
      console.log('البحث عن:', formData);
      setMessage('تم العثور على طاولات متاحة! سيتم توجيهك لصفحة النتائج...');
    } catch (error) {
      console.error('خطأ في البحث:', error);
      setMessage('حدث خطأ أثناء البحث. يرجى المحاولة مرة أخرى.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container">
      {/* Main Content */}
      <div className="main-content"><h1 className="title-glow">BOOK A TABLE</h1>
        <div>
          
          <div className="title-underline"></div>
        </div>

        <form className="glass-form" onSubmit={handleSearch}>
          {message && (
            <div className={`alert ${message.includes('خطأ') ? 'alert-danger' : 'alert-success'}`}>
              {message}
            </div>
          )}

          <div className="form-grid">
            <div className="form-group">
              <label htmlFor="location" className="form-label">Location:</label>
              <input
                type="text"
                className="form-control-glass"
                id="location"
                name="location"
                value={formData.location}
                onChange={handleInputChange}
                placeholder="اختر الموقع"
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="cuisine" className="form-label">Cuisine:</label>
              <input
                type="text"
                className="form-control-glass"
                id="cuisine"
                name="cuisine"
                value={formData.cuisine}
                onChange={handleInputChange}
                placeholder="أدخل نوع المطبخ"
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="date" className="form-label">Date:</label>
              <input
                type="date"
                className="form-control-glass"
                id="date"
                name="date"
                value={formData.date}
                onChange={handleInputChange}
                min={new Date().toISOString().split('T')[0]}
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="time" className="form-label">Time:</label>
              <input
                type="time"
                className="form-control-glass"
                id="time"
                name="time"
                value={formData.time}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="partySize" className="form-label">Party Size:</label>
              <input
                type="number"
                className="form-control-glass"
                id="partySize"
                name="partySize"
                value={formData.partySize}
                onChange={handleInputChange}
                placeholder="عدد الأشخاص"
                min="1"
                max="20"
                required
              />
            </div>

            <div className="button-group">
              <button type="submit" className="btn-search" disabled={loading}>
                {loading ? (
                  <>
                    <span className="spinner"></span>
                    Searching...
                  </>
                ) : (
                  'SEARCH'
                )}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}
